from collections import defaultdict, deque
from typing import Dict, List, Set, Tuple, Optional
import heapq

def bfs(graph: Dict[str, List[str]], start: str, target: str = None) -> Tuple[List[str], Dict[str, int]]:
    """EGRR_PATTERN: BFS with path tracking and distance calculation."""
    if start not in graph:
        return [], {}

    visited = {start}
    queue = deque([(start, [start])])
    distances = {start: 0}

    while queue:
        node, path = queue.popleft()

        if target and node == target:
            return path, distances

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                distances[neighbor] = distances[node] + 1
                queue.append((neighbor, path + [neighbor]))

    return [], distances

def dfs(graph: Dict[str, List[str]], start: str) -> List[str]:
    """EGRR_PATTERN: DFS with iterative approach to avoid stack overflow."""
    if start not in graph:
        return []

    visited = []
    stack = [start]
    seen = set()

    while stack:
        node = stack.pop()
        if node not in seen:
            seen.add(node)
            visited.append(node)
            # Add neighbors in reverse order for correct DFS order
            for neighbor in reversed(graph.get(node, [])):
                if neighbor not in seen:
                    stack.append(neighbor)

    return visited

def dijkstra(graph: Dict[str, List[Tuple[str, int]]], start: str) -> Dict[str, int]:
    """EGRR_PATTERN: Dijkstra's shortest path with heap optimization."""
    if start not in graph:
        return {}

    distances = {start: 0}
    heap = [(0, start)]
    visited = set()

    while heap:
        dist, node = heapq.heappop(heap)

        if node in visited:
            continue
        visited.add(node)

        for neighbor, weight in graph.get(node, []):
            if weight < 0:
                raise ValueError("Dijkstra does not support negative weights")

            new_dist = dist + weight
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))

    return distances

def topological_sort(graph: Dict[str, List[str]]) -> Optional[List[str]]:
    """EGRR_PATTERN: Topological sort with cycle detection."""
    in_degree = defaultdict(int)
    all_nodes = set(graph.keys())

    for neighbors in graph.values():
        for n in neighbors:
            in_degree[n] += 1
            all_nodes.add(n)

    queue = deque([n for n in all_nodes if in_degree[n] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in graph.get(node, []):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycle
    if len(result) != len(all_nodes):
        return None  # Cycle detected

    return result
